16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const PROCESSING_FEE = 5;
26	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
27	const COMPONENT_BLOCK_SIZE = 3;
28	const COMPONENT_BLOCK_PREMIUM = 60;
29	
30	const countByType = (items: QuoteItem[]): Map<string, number> => {
31	  const counts = new Map<string, number>();
32	  for (const item of items) {
33	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
34	  }
35	  return counts;
36	};
37	
38	// A component type (rune/moonstone) prices as a flat block premium when
39	// exactly COMPONENT_BLOCK_SIZE of that type are present; otherwise every
40	// item (component or not) prices per-unit from BASE_PREMIUMS.
41	const basePremiumForTypeCount = (type: string, count: number): number => {
42	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
43	    return COMPONENT_BLOCK_PREMIUM;
44	  }
45	  return BASE_PREMIUMS[type] * count;
46	};
47	
48	// NOTE: assumes the item's per-unit base price is BASE_PREMIUMS[item.type],
49	// which is true for all currently-tested cases (including lone/non-block
50	// components). This is NOT yet verified for a cursed component that's part
51	// of a priced block-of-3 (block premium is 20/item effective, not 25/item) —
52	// no test covers that combination yet, so this is left as-is pending one.
53	const curseSurcharge = (item: QuoteItem): number =>
54	  item.cursed ? BASE_PREMIUMS[item.type] / 2 : 0;
55	
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	
58	const enchantmentSurcharge = (item: QuoteItem): number =>
59	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
60	    ? (BASE_PREMIUMS[item.type] * 3) / 10
61	    : 0;
62	
63	const LOYALTY_THRESHOLD_YEARS = 2;
64	
65	// Policy-wide modifiers (loyalty, first insurance, follow-up contract) are
66	// all percentages of the pure policy base premium (sum of item base
67	// premiums, before curse/enchantment surcharges), summed together — not
68	// compounded. First-insurance surcharge always applies (per spec, every
69	// item in a quote is treated as first insurance regardless of customer
70	// history); follow-up-contract discount additionally applies whenever this
71	// is not the customer's first quote in the scenario (contractIndex > 0).
72	const policyWideModifiers = (
73	  customer: Customer,
74	  policyBase: number,
75	  contractIndex: number
76	): number => {
77	  const firstInsuranceSurcharge = policyBase / 10;
78	  const loyaltyDiscount =
79	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? (policyBase * 2) / 10 : 0;
80	  const followUpDiscount = contractIndex > 0 ? (policyBase * 15) / 100 : 0;
81	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
82	};
83	
84	export const quote = (
85	  customer: Customer,
86	  items: QuoteItem[],
87	  contractIndex: number
88	): QuoteResult => {
89	  const counts = countByType(items);
90	  let policyBase = 0;
91	  for (const [type, count] of counts) {
92	    policyBase += basePremiumForTypeCount(type, count);
93	  }
94	  // itemLevelSubtotal starts from the pure policy base and adds per-item
95	  // surcharges (curse, enchantment). Separate loop from the block above:
96	  // curse/enchantment surcharges are per-item modifiers, while the loop
97	  // above is inherently per-type-count (block-of-3 pricing can't be
98	  // computed one item at a time). Kept as a direct sum rather than an
99	  // array-of-modifiers + reduce: with just two modifiers, this is lower
100	  // mass AND reads more directly than iterating a modifier array. Revisit
101	  // the array/reduce abstraction if a third per-item modifier appears.
102	  let itemLevelSubtotal = policyBase;
103	  for (const item of items) {
104	    itemLevelSubtotal += curseSurcharge(item) + enchantmentSurcharge(item);
105	  }
106	  // Multiply-then-divide by whole numbers (not `* 1.1`) avoids float
107	  // epsilon errors for the bases seen so far. The subtotal is intentionally
108	  // left as a fraction — per spec, only the final premium is rounded, via
109	  // the single Math.ceil below.
110	  const subtotal =
111	    itemLevelSubtotal + policyWideModifiers(customer, policyBase, contractIndex);
112	  const premium = Math.ceil(subtotal + PROCESSING_FEE);
113	  return { premium };
114	};
